#include "City.h"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace yoru;
namespace {
int checks=0;
void expect(bool ok,const std::string& text){checks++;if(!ok)throw std::runtime_error(text);}
bool near(double a,double b){return std::abs(a-b)<1e-5;}
Building& b(City& c,Position p){return *c.state.tiles.at(p).building;}
void put(City& c,Position p,Kind k,int residents=0){Building v;v.kind=k;v.residents=residents;v.stock=commissioningStock(k);c.state.tiles[p].building=v;}
City ground(){City c;c.reset(true);for(int x=0;x<=16;x++){auto& t=c.state.tiles[{x,1,0}];t.road=t.power=t.water=true;}put(c,{0,0},Kind::Exchange);put(c,{1,0},Kind::Reactor);put(c,{2,0},Kind::Waterworks);put(c,{4,0},Kind::Market);c.evaluate();return c;}
void forecast(City& c){auto before=serialize(c.state);auto old=c.totals;c.evaluate();expect(serialize(c.state)==before,"Construction forecasts cannot consume, wear or move authored state");expect(near(old.powerDelivered,c.totals.powerDelivered),"New transfer forecasts are deterministic");for(auto& e:c.edges)expect(e.load>=-1e-6&&e.load<=e.capacity+1e-5,"Every new transfer shares finite physical capacity");expect(c.totals.powerDelivered+c.totals.powerCharging<=c.totals.powerSupply+1e-5,"All new motor demand is funded from real electrical supply");expect(c.totals.waterDelivered+c.totals.waterCharging+c.totals.waterLost<=c.totals.waterSupply+1e-5,"New structures do not invent water");}
}
int main(){try{
    for(auto form:{DeckForm::Slab,DeckForm::Truss,DeckForm::Podium,DeckForm::Catwalk}){City c;c.reset(true);c.buildCore({0,0,1});for(int x=1;x<=9;x++)c.buildDeck({x,0,1},form);c.evaluate();int span=deckSpan(form);expect(c.supportedTiles.count({span,0,1})&&!c.supportedTiles.count({span+1,0,1}),"Each deck material has its own physical support reach");expect(near(c.bearing[{1,0,1}].capacity,deckCapacity(form)),"Deck material sets its actual carrying capacity");}
    City rectangle;rectangle.reset(true);rectangle.beginEdit();expect(rectangle.buildPlatform({3,4,2},{1,2,2},DeckForm::Truss),"Two-corner platforms work in either corner order");expect(rectangle.state.tiles.size()==9&&rectangle.at({2,3,2})->deckForm==DeckForm::Truss,"A platform creates every cell in the selected rectangle");expect(rectangle.undo()&&rectangle.state.tiles.empty(),"One undo removes the entire platform");auto empty=serialize(rectangle.state);expect(!rectangle.buildPlatform({0,0,1},{32,1,1},DeckForm::Slab)&&serialize(rectangle.state)==empty,"Oversized platforms reject atomically");rectangle.state.freeBuild=false;rectangle.state.credits=100;auto cash=serialize(rectangle.state);expect(!rectangle.buildPlatform({0,0,1},{2,2,1},DeckForm::Podium)&&serialize(rectangle.state)==cash,"Unaffordable platforms cannot leave partially built floors");
    City light;light.reset(true);light.buildCore({0,0,1});light.buildDeck({1,0,1},DeckForm::Catwalk);light.evaluate();expect(light.at({1,0,1})->walk,"A catwalk includes its public walkway");auto authored=serialize(light.state);expect(!light.place({1,0,1},Kind::Capsule)&&!light.route({1,0,1},Layer::Road)&&!light.route({1,0,1},Layer::Rail)&&serialize(light.state)==authored,"Light catwalks reject buildings and vehicles without damaging the city");light.buildDeck({1,0,1},DeckForm::Podium);expect(light.place({1,0,1},Kind::Capsule),"A catwalk can be converted into a real building platform");auto built=serialize(light.state);expect(!light.buildDeck({1,0,1},DeckForm::Catwalk)&&serialize(light.state)==built,"A material conversion cannot invalidate an occupied building");
    City transfer;transfer.reset(true);transfer.buildCore({0,0,1});for(int x=1;x<=4;x++)transfer.buildDeck({x,0,1},DeckForm::Podium);expect(transfer.buildPier({2,0,2})&&transfer.buildPier({2,0,3}),"Individual piers can start on a transfer floor and continue upward");for(int x=2;x<=5;x++)transfer.buildDeck({x,0,3},DeckForm::Truss);put(transfer,{3,0,3},Kind::Capsule,20);transfer.evaluate();expect(b(transfer,{3,0,3}).supported&&!transfer.at({2,0,0}),"Offset upper columns do not create hidden ground foundations");bool shifted=false;for(auto flow:transfer.bearingFlows)if(flow.from==Position{2,0,2}&&flow.to==Position{2,0,1}&&flow.load>0)shifted=true;expect(shifted&&transfer.bearing[{0,0,0}].load>transfer.bearing[{2,0,3}].load,"Upper weight passes through the transfer floor to the offset foundation");transfer.beginEdit();transfer.buildDeck({2,0,1},DeckForm::Slab);transfer.evaluate();expect(!b(transfer,{3,0,3}).supported,"Replacing a transfer floor with an ordinary slab removes its ability to support an offset pier");expect(transfer.undo()&&b(transfer,{3,0,3}).supported,"Undo restores the complete offset bearing path");expect(!transfer.buildPier({20,0,2}),"A pier cannot appear in unsupported empty air");expect(transfer.probeCore({0,0,0})->unsafeResidents==20,"Existing outage probes trace the new offset bearing dependency");
    auto bridge=ground();bridge.buildCore({2,1,1});bridge.buildCore({12,1,1});for(auto p:{Position{1,0,1},{2,0,1},{2,1,1},{3,1,1},{3,0,1},{11,1,1},{11,0,1}}){bridge.buildDeck(p,DeckForm::Truss);bridge.route(p,Layer::Walk);}for(int y=-2;y<=1;y++)bridge.route({1,y,0},Layer::Road);bridge.route({0,-1,0},Layer::Road);bridge.connect({1,-2,0},{1,0,1},ConnectorKind::FootRamp);put(bridge,{3,0,1},Kind::Capsule,32);put(bridge,{11,0,1},Kind::Office);bridge.evaluate();expect(!b(bridge,{11,0,1}).walk,"Two disconnected upper courts need an actual spanning connection");expect(bridge.connect({3,1,1},{11,1,1},ConnectorKind::Skybridge),"A truss skybridge joins existing supported decks");size_t sky=bridge.state.connectors.size()-1;expect(b(bridge,{11,0,1}).walk&&b(bridge,{11,0,1}).stepFree,"A skybridge carries real step-free public circulation from its ramp approach");expect(!bridge.at({7,1,1}),"An explicit bridge creates no fake floor, pier or junction in mid-span");bool path=false;for(auto& j:bridge.journeys)for(size_t i=1;i<j.path.size();i++)if((j.path[i-1]==Position{3,1,1}&&j.path[i]==Position{11,1,1})||(j.path[i-1]==Position{11,1,1}&&j.path[i]==Position{3,1,1}))path=true;expect(path,"Worker journeys include the actual bridge edge");auto bridgeState=serialize(bridge.state);expect(!bridge.route({7,1,1},Layer::Walk)&&!bridge.buildDeck({7,1,1})&&!bridge.place({7,1,1},Kind::Garden)&&serialize(bridge.state)==bridgeState,"Bridge airspace stays clear and cannot become an accidental junction");expect(!bridge.connect({11,1,1},{3,1,1},ConnectorKind::Skybridge),"Reversed landings cannot duplicate a skybridge");bridge.toggleConnector(sky);expect(!b(bridge,{11,0,1}).walk,"Closing the bridge severs its remote court");bridge.toggleConnector(sky);forecast(bridge);
    for(int x:{2,3,11,12})for(int y=1;y<=3;y++){bridge.buildDeck({x,y,1},DeckForm::Truss);bridge.route({x,y,1},Layer::Walk);if(x<4)bridge.route({x,y,1},Layer::Power);}bridge.connect({2,1,0},{2,1,1},ConnectorKind::Riser);expect(bridge.connect({3,3,1},{11,3,1},ConnectorKind::MovingWalk),"A separate moving walk offers another public span");size_t moving=bridge.state.connectors.size()-1;expect(bridge.state.connectors[moving].power>.99,"Moving-walk motors draw actual electrical service");int fast=0;double poweredCapacity=0;for(auto e:bridge.edges)if(e.connector==int(moving)&&e.layer==Layer::Walk){fast=e.cost;poweredCapacity=e.capacity;}bridge.toggle({1,0});bool slow=false;for(auto e:bridge.edges)if(e.connector==int(moving)&&e.layer==Layer::Walk)slow=e.cost>fast&&e.capacity<poweredCapacity;expect(slow&&b(bridge,{11,0,1}).walk,"A power cut slows a moving walk into a smaller passive walkway");forecast(bridge);bridge.toggle({1,0});
    auto stairs=ground();stairs.buildCore({3,3,1});stairs.buildDeck({4,3,1},DeckForm::Truss);put(stairs,{4,3,1},Kind::Capsule,20);expect(stairs.connect({3,1,0},{3,3,1},ConnectorKind::Escalator),"Escalators connect short inclined landings");expect(stairs.state.connectors.back().power>.99&&b(stairs,{4,3,1}).walk&&!b(stairs,{4,3,1}).stepFree,"A powered escalator serves general journeys without masquerading as step-free access");stairs.toggle({1,0});expect(b(stairs,{4,3,1}).walk&&b(stairs,{4,3,1}).blackoutExit&&!b(stairs,{4,3,1}).blackoutStepFree,"An unpowered escalator remains a passive stair route");stairs.buildCore({6,4,1});for(int x=3;x<=6;x++){stairs.buildDeck({x,4,1},DeckForm::Truss);stairs.route({x,4,1},Layer::Walk);}expect(stairs.connect({6,1,0},{6,4,1},ConnectorKind::FootRamp)&&b(stairs,{4,3,1}).blackoutStepFree,"A separate pedestrian ramp preserves step-free access without electricity");expect(!b(stairs,{4,3,1}).road,"A pedestrian ramp creates no vehicle loading network");forecast(stairs);
    auto express=ground();expect(express.connect({6,1,0},{6,1,4},ConnectorKind::ExpressLift),"Express lifts can skip several strata");expect(express.state.connectors.size()==1,"One express trip is one capacity-sharing connection");for(int z:{2,4}){express.buildDeck({6,0,z});put(express,{6,0,z},Kind::Capsule,20);}express.evaluate();expect(b(express,{6,0,4}).walk&&b(express,{6,0,4}).stepFree&&!b(express,{6,0,2}).walk,"Express doors serve only their two stops");expect(!express.at({6,1,2})->walk,"A passing express shaft does not create an intermediate landing");expect(near(connectorPower(express.state.connectors[0]),16),"Express motor demand scales with the vertical span");express.route({6,1,2},Layer::Walk);express.evaluate();expect(!b(express,{6,0,2}).walk,"Painting an intermediate concourse cannot attach it to a passing express cabin");express.toggle({1,0});expect(!b(express,{6,0,4}).walk,"A powered express connection stops during a grid outage");express.toggle({1,0});forecast(express);
    expect(!connectorGeometry({0,0,1},{8,1,1},ConnectorKind::Skybridge)&&connectorGeometry({0,0,1},{8,8,1},ConnectorKind::Skybridge),"Skybridges support straight and 45-degree diagonal geometry, without arbitrary bent jumps");expect(!connectorGeometry({0,0,0},{4,0,0},ConnectorKind::Skybridge)&&!connectorGeometry({0,0,1},{13,0,1},ConnectorKind::Skybridge),"Skybridges have explicit elevated span limits");
    City crossing;crossing.reset(true);for(auto p:{Position{0,0,1},{3,3,1},{0,1,1},{3,-2,1}})crossing.buildCore(p);expect(crossing.connect({0,0,1},{3,3,1},ConnectorKind::Skybridge),"Diagonal bridges are real supported spans");auto crossed=serialize(crossing.state);expect(!crossing.connect({0,1,1},{3,-2,1},ConnectorKind::Skybridge)&&serialize(crossing.state)==crossed,"Even a crossing between tile centres is rejected on the same plane");crossing.buildCore({0,1,2});crossing.buildCore({3,-2,2});expect(crossing.connect({0,1,2},{3,-2,2},ConnectorKind::Skybridge),"The same crossing is valid at a different physical elevation");
    for(auto& kit:City::structures()){City frame;frame.reset(true);frame.beginEdit();expect(frame.stamp({0,0,0},kit),"Every reusable frame places atomically");for(auto& [p,t]:frame.state.tiles)if(t.deck||t.column)expect(frame.supportedTiles.count(p),"A frame's empty structure has a complete bearing path: "+kit.name);expect(frame.totals.population==0,"Structural frames invent no residents");expect(frame.undo()&&frame.state.tiles.empty()&&frame.state.connectors.empty(),"A whole structural frame and its connections undo together");}
    City blocked;blocked.reset(true);put(blocked,{6,0,1},Kind::Garden);blocked.state.tiles[{6,0,1}].deck=true;auto obstacle=serialize(blocked.state);expect(!blocked.stamp({0,0,0},City::structures()[1])&&serialize(blocked.state)==obstacle,"A frame cannot place a bridge through a pre-existing occupied volume");
    auto saved=serialize(bridge.state);expect(serialize(deserialize(saved))==saved,"Schema six preserves material forms and new connection kinds exactly");for(int i=0;i<4;i++){auto bad=saved;if(i==0)bad["tiles"][0]["deckForm"]=4;if(i==1){bad["tiles"][0]["deck"]=false;bad["tiles"][0]["deckForm"]=2;}if(i==2)bad["connectors"][0]["kind"]=10;if(i==3)bad["connectors"][int(sky)]["b"]["x"]=100;bool rejected=false;try{deserialize(bad);}catch(...){rejected=true;}expect(rejected,"Malformed construction geometry or material state is rejected");}
    auto legacy=serialize(ground().state);legacy["version"]=5;for(auto& tile:legacy["tiles"])tile.erase("deckForm");auto imported=deserialize(legacy);for(auto& [p,t]:imported.tiles){(void)p;expect(t.deckForm==DeckForm::Slab,"V5 cities retain neutral ordinary slab material");}
    for(int tick=0;tick<12;tick++){forecast(bridge);bridge.step();forecast(express);express.step();}std::cout<<"PASS "<<checks<<" construction material, offset bearing, bridge and circulation checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
